-- Fixture-only Feature 31 history; it has no product proposal, wallet, venue, or external owner.
CREATE OR REPLACE FUNCTION portfolio_sizing_append_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'portfolio sizing history is immutable'; END $$;
CREATE TABLE IF NOT EXISTS portfolio_sizing_runs(operator_test_id text NOT NULL,run_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS portfolio_sizing_decisions(operator_test_id text NOT NULL,run_hash char(64) NOT NULL,artifact_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,run_hash,artifact_hash),FOREIGN KEY(operator_test_id,run_hash) REFERENCES portfolio_sizing_runs(operator_test_id,run_hash));
CREATE TABLE IF NOT EXISTS portfolio_sizing_request_claims(operator_test_id text NOT NULL,idempotency_key text NOT NULL,request_hash char(64) NOT NULL,run_hash char(64) NOT NULL,payload_hash char(64) NOT NULL,payload jsonb NOT NULL,PRIMARY KEY(operator_test_id,idempotency_key),FOREIGN KEY(operator_test_id,run_hash) REFERENCES portfolio_sizing_runs(operator_test_id,run_hash));
DO $$ DECLARE tab text; BEGIN FOREACH tab IN ARRAY ARRAY['portfolio_sizing_runs','portfolio_sizing_decisions','portfolio_sizing_request_claims'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS portfolio_sizing_immutable ON %I',tab); EXECUTE format('CREATE TRIGGER portfolio_sizing_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION portfolio_sizing_append_only()',tab); END LOOP; END $$;
CREATE INDEX IF NOT EXISTS portfolio_sizing_run_scope_idx ON portfolio_sizing_runs(operator_test_id,created_at);
